Here is an example code snippet in C using LLVM-C to codegen a Fibonacci function:

```c
#include <stdio.h>
#include <llvm-c/Core.h>
#include <llvm-c/ExecutionEngine.h>
#include <llvm-c/BitWriter.h>

int main() {
    // Create new LLVM module
    LLVMModuleRef module = LLVMModuleCreateWithName("fibonacci");

    // Define the function prototype
    LLVMTypeRef param_types[] = { LLVMInt32Type() };
    LLVMTypeRef func_type = LLVMFunctionType(LLVMInt32Type(), param_types, 1, 0);
    LLVMValueRef fib_func = LLVMAddFunction(module, "fib", func_type);
    LLVMValueRef n_param = LLVMGetParam(fib_func, 0);
    LLVMSetValueName(n_param, "n");

    // Create basic blocks
    LLVMBasicBlockRef entry = LLVMAppendBasicBlock(fib_func, "entry");
    LLVMBasicBlockRef if_cond = LLVMAppendBasicBlock(fib_func, "if.cond");
    LLVMBasicBlockRef if_true = LLVMAppendBasicBlock(fib_func, "if.true");
    LLVMBasicBlockRef if_false = LLVMAppendBasicBlock(fib_func, "if.false");

    // Build function body
    LLVMBuilderRef builder = LLVMCreateBuilder();
    LLVMPositionBuilderAtEnd(builder, entry);

    // Implement Fibonacci sequence calculation
    LLVMBuildCondBr(builder, LLVMBuildICmp(builder, LLVMIntEQ, n_param, LLVMConstInt(LLVMInt32Type(), 0, 0), ""), if_false, if_cond);

    LLVMPositionBuilderAtEnd(builder, if_cond);
    LLVMValueRef fib_n_minus_1 = LLVMBuildSub(builder, n_param, LLVMConstInt(LLVMInt32Type(), 1, 0), "");
    LLVMValueRef call_1 = LLVMBuildCall(builder, fib_func, &fib_n_minus_1, 1, "");
    LLVMBuildBr(builder, if_true);

    LLVMPositionBuilderAtEnd(builder, if_true);
    LLVMBuildRet(builder, LLVMBuildAdd(builder, call_1, LLVMBuildAdd(builder, call_1, LLVMConstInt(LLVMInt32Type(), -1, 0), ""), ""));

    LLVMPositionBuilderAtEnd(builder, if_false);
    LLVMBuildRet(builder, LLVMConstInt(LLVMInt32Type(), 0, 0));

    LLVMDisposeBuilder(builder);

    // Verify and optimize the code
    LLVMVerifyModule(module, LLVMReturnStatusAction, NULL);

    // Emit machine code
    LLVMExecutionEngineRef engine;
    char *error = NULL;
    LLVMCreateExecutionEngineForModule(&engine, module, &error);
    if (error) {
        fprintf(stderr, "Error: %s\n", error);
        LLVMDisposeMessage(error);
        return 1;
    }

    // Get the function pointer
    int(*fib)(int) = (int(*)(int))LLVMGetPointerToGlobal(engine, fib_func);

    // Test the Fibonacci function
    int result = fib(10);
    printf("Fibonacci of 10 is %d\n", result);

    // Cleanup
    LLVMDisposeExecutionEngine(engine);
    LLVMDisposeModule(module);

    return 0;
}
```

