```metal
kernel void gaussianBlur(texture2d<half, access::read> inputImage [[texture(0)]],
                         texture2d<half, access::write> outputImage [[texture(1)]],
                         constant float &sigma [[buffer(0)]],
                         uint2 gid [[thread_position_in_grid]])
{
