Creating a Terraform module to set up an API Gateway that pushes REST POST requests directly to a DynamoDB table involves several resources. Below is a simple example to help you get started. This module will create:

1. **DynamoDB Table**: To store the data received from the API Gateway.
2. **API Gateway**: To set up an endpoint to receive POST requests.
3. **IAM Role and Policy**: To allow API Gateway to access the DynamoDB table.

### Step 1: Create the Terraform Module Directory Structure

Organize your module files as follows:

```
api-gw-dynamodb/
├── main.tf
├── variables.tf
└── outputs.tf
```

### Step 2: main.tf

In the `main.tf` file, define the necessary AWS resources.

```hcl
provider "aws" {
  region = var.region
}

resource "aws_dynamodb_table" "api_data" {
  name           = var.dynamodb_table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = var.api_name
  description = "API Gateway to push data to DynamoDB"
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = var.api_resource_path
}

resource "aws_api_gateway_method" "post_method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id             = aws_api_gateway_rest_api.api.id
  resource_id             = aws_api_gateway_resource.resource.id
  http_method             = aws_api_gateway_method.post_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = "arn:aws:apigateway:${var.region}:dynamodb:action/PutItem"

  request_templates = {
    "application/json" = <<-EOF
    {
      "TableName": "${aws_dynamodb_table.api_data.name}",
      "Item": {
        "id": {
          "S": "$context.requestId"
        },
        "body": {
          "S": "$input.body"
        }
      }
    }
    EOF
  }
}

resource "aws_api_gateway_deployment" "deployment" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  depends_on = [aws_api_gateway_integration.integration]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "stage" {
  stage_name    = var.api_stage_name
  rest_api_id   = aws_api_gateway_rest_api.api.id
  deployment_id = aws_api_gateway_deployment.deployment.id
}

resource "aws_iam_role" "api_gateway_role" {
  name = "api-gateway-dynamodb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway_policy" {
  name = "api-gateway-dynamodb-policy"
  role = aws_iam_role.api_gateway_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "dynamodb:PutItem"
        Resource = aws_dynamodb_table.api_data.arn
      }
    ]
  })
}
```

### Step 3: variables.tf

Define the variables required for the module.

```hcl
variable "region" {
  description = "The AWS region to deploy to"
  type        = string
}

variable "dynamodb_table_name" {
  description = "The name of the DynamoDB table"
  type        = string
}

variable "api_name" {
  description = "The name of the API Gateway"
  type        = string
}

variable "api_resource_path" {
  description = "The path for the API Gateway resource"
  type        = string
}

variable "api_stage_name" {
  description = "The stage name for the API"
  type        = string
}
```

### Step 4: outputs.tf

Define the outputs for the module.

```hcl
output "api_endpoint" {
  description = "The endpoint URL of the API Gateway"
  value       = aws_api_gateway_stage.stage.invoke_url
}
```

### Usage

After creating the module, you can use it in your Terraform configuration like this:

```hcl
module "api_gw_to_dynamo" {
  source               = "./api-gw-dynamodb"
  region               = "us-west-2"
  dynamodb_table_name  = "MyAPITable"
  api_name             = "MyAPI"
  api_resource_path    = "myresource"
  api_stage_name       = "dev"
}
```

This will create an API Gateway that listens for POST requests and pushes the data directly to a specified DynamoDB table. Remember to tailor the configurations to fit your security policies and application needs (e.g., API Gateway methods, authorization settings, etc.).

