### Basic Template for a React Hook to Connect to a GraphQL API

Here's a basic example of a React hook that connects to a GraphQL API using `fetch`:

```javascript
import { useState, useEffect } from 'react';

const useGraphQLQuery = (query, variables = {}) => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const response = await fetch('https://your-graphql-endpoint.com/graphql', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
          },
          body: JSON.stringify({
            query: query,
            variables: variables,
          }),
        });

        if (!response.ok) {
          throw new Error('Network response was not ok');
        }

        const result = await response.json();
        setData(result.data);
      } catch (error) {
        setError(error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [query, variables]);

  return { data, loading, error };
};

export default useGraphQLQuery;
```

### Usage Example

```javascript
import React from 'react';
import useGraphQLQuery from './useGraphQLQuery';

const GetDataComponent = () => {
  const GET_DATA_QUERY = `
    query GetData($id: ID!) {
      data(id: $id) {
        id
        name
      }
    }
  `;

  const { data, loading, error } = useGraphQLQuery(GET_DATA_QUERY, { id: '1' });

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error: {error.message}</p>;

  return (
    <div>
      <h1>Data:</h1>
      <p>{data ? `Name: ${data.name}` : 'No data found'}</p>
    </div>
  );
};

export default GetDataComponent;
```

