using namespace std;

int longestIncreasingSubsequence(int arr[], int n) {
    if (n == 0) return 0;

    vector<int> lis(n, 1);

    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (arr[i] > arr[j] && lis[i] < lis[j] + 1) {
                lis[i] = lis[j] + 1;
            }
        }
    }

    int maxLength = 0;
    for (int i = 0; i < n; ++i) {
        if (lis[i] > maxLength) {
            maxLength = lis[i];
        }
    }

    return maxLength;
}

int main() {
    int arr[] = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3};
    int n = sizeof(arr) / sizeof(arr[0]);

    cout << "Length of Longest Increasing Subsequence is " << longestIncreasingSubsequence(arr, n) << endl;

    return 0;
}
