```cpp
#include <iostream>
#include <vector>
#include <algorithm>

int lengthOfLIS(int arr[], int n) {
    std::vector<int> dp(n, 1);
    int maxLength = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[i] > arr[j]) {
                dp[i] = std::max(dp[i], dp[j] + 1);
            }
        }
        maxLength = std::max(maxLength, dp[i]);
    }

    return maxLength;
}

int main() {
    int arr[] = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3};
    int n = sizeof(arr) / sizeof(arr[0]);

    int longestIncreasingSubsequenceLength = lengthOfLIS(arr, n);

    std::cout << "Length of the longest increasing subsequence: " << longestIncreasingSubsequenceLength << std::endl;

    return 0;
}
```

