To solve this problem, you'll want to perform a depth-first search (DFS) on the directed acyclic graph (DAG) while recording the total score of paths from the start node to the end node. Since the goal is to maximize the total score, you'll keep track of the maximum score found as you traverse the graph. Here's a Python implementation to achieve this:

```python
def is_single_letter_diff(word1, word2):
    # Check if two words differ by exactly one letter
    if len(word1) != len(word2):
        return False
    count_diff = 0
    for a, b in zip(word1, word2):
        if a != b:
            count_diff += 1
            if count_diff > 1:
                return False
    return count_diff == 1

def build_graph(words):
    # Build a list of edges (word1 -> word2, weight)
    edges = []
    for i, word1 in enumerate(words):
        for j, word2 in enumerate(words):
            if i != j and is_single_letter_diff(word1, word2):
                # Assign a weight to the edge, can be adjusted or randomly set
                weight = 1  # Example: you can modify this logic
                edges.append((word1, word2, weight))
    return edges

def dfs(current, end, graph, visited, memo):
    if current == end:
        return 0
    if current in visited:
        return float('-inf')
    if current in memo:
        return memo[current]

    visited.add(current)

    max_score = float('-inf')
    for neighbor, weight in graph.get(current, []):
        score = weight + dfs(neighbor, end, graph, visited, memo)
        max_score = max(max_score, score)

    visited.remove(current)
    memo[current] = max_score
    return max_score

def max_path_score(words, start, end):
    # Build the graph as an adjacency list with weights
    edges = build_graph(words)
    graph = {}
    for word1, word2, weight in edges:
        if word1 not in graph:
            graph[word1] = []
        graph[word1].append((word2, weight))

    visited = set()
    memo = {}
    return dfs(start, end, graph, visited, memo)

# Example dictionary words
words = ["hit", "hot", "dot", "dog", "cog", "log"]
start_word = "hit"
end_word = "cog"

print(max_path_score(words, start_word, end_word))
```

### Explanation:
- **is_single_letter_diff** checks if two words differ by exactly one letter.
- **build_graph** creates the DAG by listing all edges that connect words differing by a single letter. Each edge is given a default weight of 1, but you could adjust this logic depending on your specific requirements.
- **dfs** performs a depth-first search to find the path with the maximum score from the start node to the end node while keeping track of visited nodes to avoid cycles.
- **max_path_score** constructs the graph and calculates the maximum score between the start and end nodes. 

This setup assumes the weights could be more dynamically assigned and that the start and end words are connected within the provided `words` list. Adjust the edge weight logic as needed for your specific application.

