    string a = num1.substr(0, num1.size()-mid);
    string b = num1.substr(num1.size()-mid);
    string c = num2.substr(0, num2.size()-mid);
    string d = num2.substr(num2.size()-mid);

    // Recursively calculate the three multiplications required by Karatsuba formula
    string ac = karatsuba(a, c);
    string bd = karatsuba(b, d);

    // Calculate ad+bc using Karatsuba formula
    string abcd = karatsuba(to_string(stoi(a) + stoi(b)), to_string(stoi(c) + stoi(d)));
    string adbc = to_string(stoi(abcd) - stoi(ac) - stoi(bd));

    // Construct the final result using the three products computed above
    string result = ac + string(2*mid, '0') + adbc + string(mid, '0') + bd;

    return result;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        cout << "Usage: ./karatsuba num1 num2" << endl;
        return 1;
    }

    string num1 = argv[1];
    string num2 = argv[2];

    string result = karatsuba(num1, num2);
    cout << "Product: " << result << endl;

    return 0;
}
```

To compile and run the program, save the code in a file named `karatsuba.cpp` and then use the following commands:
```
g++ -o karatsuba karatsuba.cpp
./karatsuba 12345 6789
```

Replace `12345` and `6789` with the numbers you want to multiply using Karatsuba algorithm.

