Below is an example of a UART transmitter in VHDL that takes an 8-bit word as input and divides the output clock according to a configurable amount. The transmission is initiated by a one-cycle high pulse to the `W` input.

```vhdl
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity UART_Transmitter is
    Generic (
        CLOCK_DIVIDER : integer := 1  -- Configurable division factor for the output clock
    );
    Port (
        clk     : in std_logic;        -- Input clock
        reset   : in std_logic;        -- Active high reset
        W       : in std_logic;        -- Start transmission by pulsing high
        data_in : in std_logic_vector(7 downto 0); -- 8-bit data to be transmitted
        tx      : out std_logic            -- UART transmit line
    );
end UART_Transmitter;

architecture Behavioral of UART_Transmitter is

    type state_type is (IDLE, START, DATA, STOP);
    signal state       : state_type := IDLE;
    signal bit_counter : integer range 0 to 7 := 0;
    signal clock_count : integer := 0;
    signal baud_tick   : std_logic := '0';
    signal tx_reg      : std_logic := '1';
    signal tx_data     : std_logic_vector(7 downto 0);

begin

    -- Process for generating baud rate tick
    process(clk, reset)
    begin
        if reset = '1' then
            clock_count <= 0;
            baud_tick <= '0';
        elsif rising_edge(clk) then
            if clock_count < CLOCK_DIVIDER / 2 - 1 then
                clock_count <= clock_count + 1;
                baud_tick <= '0';
            else
                clock_count <= 0;
                baud_tick <= '1';
            end if;
        end if;
    end process;

    -- Process for UART transmission state machine
    process(clk, reset)
    begin
        if reset = '1' then
            state <= IDLE;
            tx_reg <= '1';
            bit_counter <= 0;
        elsif rising_edge(clk) then
            if baud_tick = '1' then
                case state is
                    when IDLE =>
                        tx_reg <= '1';  -- Idle state keeps tx high
                        if W = '1' then
                            state <= START;
                            tx_data <= data_in;
                        end if;
                    when START =>
                        tx_reg <= '0';  -- Start bit
                        state <= DATA;
                        bit_counter <= 0;
                    when DATA =>
                        tx_reg <= tx_data(bit_counter);  -- Transmit data bits
                        if bit_counter = 7 then
                            state <= STOP;
                        else
                            bit_counter <= bit_counter + 1;
                        end if;
                    when STOP =>
                        tx_reg <= '1';  -- Stop bit
                        state <= IDLE;
                end case;
            end if;
        end if;
    end process;

    -- Assign tx register to output
    tx <= tx_reg;

end Behavioral;
```

**Explanation:**

1. **Entity Declaration:** The `UART_Transmitter` entity has inputs `clk`, `reset`, `W`, and `data_in`, and one output `tx`. The `CLOCK_DIVIDER` generic allows configuration of the baud rate divisor.

2. **Architecture:**
    - **Baud Rate Generator:** A process is used to generate a slower clock-enable signal, `baud_tick`, by dividing the input `clk` using `CLOCK_DIVIDER`.
    - **State Machine:** The main functionality is implemented through a state machine with states `IDLE`, `START`, `DATA`, and `STOP`.
    - **Transmission Process:** On detecting `W` going high, the state transitions to `START` to initiate transmission. The `DATA` state shifts out bits, and `STOP` state appends a stop bit. The process returns to `IDLE` upon completing transmission.

3. **Output Assignments:** The `tx` output is driven by the `tx_reg` signal which reflects the current state and data being sent.

Ensure that the `CLOCK_DIVIDER` value is chosen such that the input clock divided by it gives you the desired baud rate frequency. Also, remember this design needs a clock source and an appropriate `CLOCK_DIVIDER` to function correctly in an FPGA or simulator environment.

