  {1, 2, 3},
  {4, 5, 6},
  {7, 8, 9}
};

int outputMatrix[MATRIX_SIZE] = {0};  // Result of multiplication (1D for this example)

void setup() {
  // Initialize serial communication
  Serial.begin(9600);

  // Initialize PDM microphones
  PDM.begin(1, 8000);  // Mono input, 8 kHz sample rate

  // Specify the callback function for PDM data
  PDM.onReceive(onPDMdata);
}

void loop() {
