Sure, here is an example of C code that creates an array and then resizes it to fit one more element:

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int size = 5; // initial size of the array
    int *arr = (int*)malloc(size * sizeof(int)); // creating an array of size 5

    // Checking if memory was allocated successfully
    if(arr == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Initializing the array
    for(int i = 0; i < size; i++) {
        arr[i] = i;
    }

    // Resizing the array
    size++; // increase the size by one
    arr = (int*)realloc(arr, size * sizeof(int)); // resizing the array

    // Checking if memory was reallocated successfully
    if(arr == NULL) {
        printf("Memory reallocation failed\n");
        return 1;
    }

    // Adding one more element to the array
    arr[size - 1] = size - 1;

    // Printing the elements of the resized array
    for(int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }

    // Freeing the memory used by the array
    free(arr);

    return 0;
}
```

In this code, we first create an array of size 5 using `malloc` and initialize it with some values. Then, we resize the array by increasing its size by one using `realloc` and add one more element to the array. Finally, we print out the elements of the resized array and free the memory used by the array.

