Here is a simple implementation of a snake game in Python using the `pygame` library:

```python
import pygame
import random

# Define constants
SCREEN_WIDTH = 800
SCREEN_HEIGHT = 600
GRID_SIZE = 20
SNAKE_SIZE = 20
FRAME_RATE = 10
BLACK = (0, 0, 0)
WHITE = (255, 255, 255)
GREEN = (0, 255, 0)
RED = (255, 0, 0)

# Initialize pygame
pygame.init()
screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))
pygame.display.set_caption("Snake Game")
clock = pygame.time.Clock()

# Define classes
class Snake:
    def __init__(self):
        self.body = [[100, 100], [80, 100], [60, 100]]
        self.direction = "RIGHT"

    def move(self):
        head = self.body[0].copy()

        if self.direction == "RIGHT":
            head[0] += GRID_SIZE
        elif self.direction == "LEFT":
            head[0] -= GRID_SIZE
        elif self.direction == "UP":
            head[1] -= GRID_SIZE
        elif self.direction == "DOWN":
            head[1] += GRID_SIZE

        self.body.insert(0, head)
        self.body.pop()

    def grow(self):
        tail = self.body[-1].copy()
        self.body.append(tail)

    def check_collision(self):
        if self.body[0][0] < 0 or self.body[0][0] >= SCREEN_WIDTH or self.body[0][1] < 0 or self.body[0][1] >= SCREEN_HEIGHT:
            return True

        if self.body[0] in self.body[1:]:
            return True

        return False

class Apple:
    def __init__(self):
        self.position = [random.randrange(0, SCREEN_WIDTH, GRID_SIZE), random.randrange(0, SCREEN_HEIGHT, GRID_SIZE)]

    def respawn(self):
        self.position = [random.randrange(0, SCREEN_WIDTH, GRID_SIZE), random.randrange(0, SCREEN_HEIGHT, GRID_SIZE)]

# Create objects
snake = Snake()
apple = Apple()

# Game loop
running = True
while running:
    screen.fill(BLACK)

    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False

        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_UP and snake.direction != "DOWN":
                snake.direction = "UP"
            elif event.key == pygame.K_DOWN and snake.direction != "UP":
                snake.direction = "DOWN"
            elif event.key == pygame.K_LEFT and snake.direction != "RIGHT":
                snake.direction = "LEFT"
            elif event.key == pygame.K_RIGHT and snake.direction != "LEFT":
                snake.direction = "RIGHT"

    snake.move()

    if snake.body[0] == apple.position:
        snake.grow()
        apple.respawn()

    if snake.check_collision():
        running = False

    pygame.draw.rect(screen, RED, [*apple.position, SNAKE_SIZE, SNAKE_SIZE])

    for segment in snake.body:
        pygame.draw.rect(screen, GREEN, [*segment, SNAKE_SIZE, SNAKE_SIZE])

    pygame.display.flip()
    clock.tick(FRAME_RATE)

pygame.quit()
```

This code creates a simple snake game where the player controls a snake and tries to eat apples to grow longer. The game ends if the snake hits the boundaries of the screen or collides with itself. You can run this code in a Python environment with the `pygame` library installed.

