#include <flutter/encodable_value.h>
#include <string>
#include <stdexcept>

std::string ConvertEncodableValueToString(const flutter::EncodableValue &value) {
    // Check if the EncodableValue contains a string
    if (std::holds_alternative<std::string>(value)) {
        return std::get<std::string>(value);
    }

    // If the value is not directly a string, handle other converible types
    // depending on what your particular use case needs. For example:
    else if (std::holds_alternative<int>(value)) {
        return std::to_string(std::get<int>(value));
    }
    else if (std::holds_alternative<double>(value)) {
        return std::to_string(std::get<double>(value));
    }
    else if (std::holds_alternative<bool>(value)) {
        return std::get<bool>(value) ? "true" : "false";
    }

    // Add additional type checks as necessary

    // If none of the types matched, return an empty string or throw an error
    throw std::runtime_error("EncodableValue does not contain a string-compatible type.");
}

int main() {
    // Example usage
    flutter::EncodableValue encodable_string("Hello, Flutter!");
    flutter::EncodableValue encodable_int(42);

