Here is one way to convert an array of JSON objects to CSV format in JavaScript:

```javascript
function convertArrayOfJsonToCSV(data) {
  // Extract unique keys from all JSON objects in the array
  let keys = data.reduce((acc, obj) => {
    Object.keys(obj).forEach(key => {
      if (!acc.includes(key)) {
        acc.push(key);
      }
    });
    return acc;
  }, []);

  // Write CSV header row with all unique keys
  let csv = keys.join(',') + '\n';

  // Write CSV data rows for each JSON object
  data.forEach(obj => {
    let row = keys.map(key => obj[key] || '').join(',');
    csv += row + '\n';
  });

  return csv;
}

// Example array of JSON objects
let jsonData = [
  { name: 'Alice', age: 30, city: 'New York' },
  { name: 'Bob', age: 25, country: 'USA' },
  { name: 'Charlie', age: 35, city: 'Los Angeles', profession: 'Developer' }
];

// Convert array of JSON objects to CSV
