  attachInterrupt(MIC_PIN_LEFT, readLeftMic, CHANGE);
  attachInterrupt(MIC_PIN_RIGHT, readRightMic, CHANGE);

  // Create microphone processing task
  xTaskCreatePinnedToCore(micProcessingTask, "Mic Processing Task", 2048, NULL, 1, &micReadingTaskHandle, 0);
}

void loop() {
  // Simulate sound processing by giving semaphore every 100ms
  vTaskDelay(pdMS_TO_TICKS(100));
  xSemaphoreGive(xSemaphore);
}
