```javascript
import { useEffect, useRef } from 'react';

const useScrollIntoViewIfNeeded = (elementRef) => {
  useEffect(() => {
    const scrollIfNeeded = () => {
      if (elementRef.current) {
        const rect = elementRef.current.getBoundingClientRect();
        const windowHeight = window.innerHeight;

        // Check if the bottom of the element is out of view
        if (rect.bottom > windowHeight) {
          elementRef.current.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }
      }
    };

    scrollIfNeeded();
    // Optionally, you could add event listeners if you want to constantly check the visibility
    // For example, on window resize or scroll event
    window.addEventListener('resize', scrollIfNeeded);
    window.addEventListener('scroll', scrollIfNeeded);

    // Clean up event listeners on component unmount
    return () => {
      window.removeEventListener('resize', scrollIfNeeded);
      window.removeEventListener('scroll', scrollIfNeeded);
    };
  }, [elementRef]);
};

// Usage example in a functional component
const MyComponent = () => {
  const myElementRef = useRef(null);

  useScrollIntoViewIfNeeded(myElementRef);

  return (
    <div>
      {/* Other content */}
      <div ref={myElementRef} style={{ marginBottom: '100vh' }}>
        Your Content
      </div>
    </div>
  );
};

export default MyComponent;
```

### Explanation:
