  while (stepperX.distanceToGo() != 0 || stepperY.distanceToGo() != 0 || stepperFocus.distanceToGo() != 0 || stepperZ.distanceToGo() != 0) {
    stepperX.run();
    stepperY.run();
    stepperFocus.run();
    stepperZ.run();
  }

  // Pause for demonstration purposes
  delay(1000);

  // Move back to zero position
  stepperX.moveTo(0);
  stepperY.moveTo(0);
  stepperFocus.moveTo(0);
  stepperZ.moveTo(0);

