To display Pascal's triangle in an HTML canvas using JavaScript, you'll need a function to calculate the values in Pascal's triangle and then draw it on the canvas. Here’s a simple example:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Pascal's Triangle</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="pascalsTriangle" width="400" height="400"></canvas>
    <script>
        function drawPascalsTriangle(context, rows) {
            // Start position
            let startX = 200;
            let startY = 20;
            let rowHeight = 30;

            for (let n = 0; n < rows; n++) {
                let x = startX - (n * 15); // Adjust start for each row
                for (let k = 0; k <= n; k++) {
                    let val = calculatePascalValue(n, k);
                    context.fillText(val, x, startY + (n * rowHeight));
                    x += 30; // Space between numbers
                }
            }
        }

        function calculatePascalValue(n, k) {
            if (k === 0 || k === n) {
                return 1;
            } else {
                return calculatePascalValue(n - 1, k - 1) + calculatePascalValue(n - 1, k);
            }
        }

        // Draw the triangle
        window.onload = function() {
            const canvas = document.getElementById('pascalsTriangle');
            const context = canvas.getContext('2d');
            context.font = '16px Arial';

            drawPascalsTriangle(context, 10); // Draw 10 rows of Pascal's triangle
        };
    </script>
</body>
</html>
```

### Explanation:

1. **Canvas Setup:**
