To display Pascal's triangle in an HTML canvas using JavaScript, you can use the following code:

```html
<!DOCTYPE html>
<html>
<head>
  <title>Pascal's Triangle</title>
</head>
<body>
  <canvas id="canvas" width="800" height="400"></canvas>

  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const numRows = 10;

    // Function to calculate factorial of a number
    function factorial(n) {
      if (n === 0) {
        return 1;
      } else {
        return n * factorial(n - 1);
      }
    }

    // Function to calculate binomial coefficient
    function binomialCoefficient(n, k) {
      return factorial(n) / (factorial(k) * factorial(n - k));
    }

    // Function to draw Pascal's triangle
    function drawPascalsTriangle() {
      let x = canvas.width / 2;
      let y = 50;
      let rowWidth = 20;

      for (let i = 0; i < numRows; i++) {
        let startX = x - (rowWidth * i) / 2;

        for (let j = 0; j <= i; j++) {
          let value = binomialCoefficient(i, j);

          ctx.fillText(value, startX + j * rowWidth, y);
        }

        y += 30;
      }
    }

    ctx.font = '14px Arial';
    ctx.fillStyle = 'black';
    drawPascalsTriangle();
  </script>
</body>
</html>
```

This code will draw Pascal's triangle up to a specified number of rows (in this case, 10) on an HTML canvas element. It calculates the binomial coefficient for each cell in the triangle using the factorial function, and then draws the values on the canvas using the fillText method.

