const canvas = document.getElementById('pascalsTriangleCanvas');
const ctx = canvas.getContext('2d');

const triangleRows = 10;
const triangle = createPascalsTriangle(triangleRows);

// Function to create Pascal's Triangle
function createPascalsTriangle(rows) {
    let triangle = [];

    for (let i = 0; i < rows; i++) {
        triangle[i] = new Array(i + 1);
        triangle[i][0] = triangle[i][i] = 1;

        for (let j = 1; j < i; j++) {
            triangle[i][j] = triangle[i - 1][j - 1] + triangle[i - 1][j];
        }
    }

    return triangle;
}

// Function to draw Pascal's Triangle on the canvas
function drawPascalsTriangle(triangle) {
    const triangleHeight = triangle.length;
    const triangleWidth = triangle[triangleHeight - 1].length * 20; // Adjust based on canvas dimensions

    canvas.width = triangleWidth;
    canvas.height = triangleHeight * 20; // Adjust based on canvas dimensions

    ctx.fillStyle = 'black';
    ctx.font = '12px Arial';

    for (let i = 0; i < triangleHeight; i++) {
        for (let j = 0; j < triangle[i].length; j++) {
            ctx.fillText(triangle[i][j].toString(), j * 20, i * 20);
        }
    }
}

drawPascalsTriangle(triangle);
