architecture Behavioral of range_adjuster is
  signal a_internal : STD_LOGIC_VECTOR(31 DOWNTO 0) := (others => '0');
  signal max_internal : STD_LOGIC_VECTOR(31 DOWNTO 0) := (others => '0');
  signal min_internal : STD_LOGIC_VECTOR(31 DOWNTO 0) := (others => '0');
  signal result_internal : STD_LOGIC_VECTOR(31 DOWNTO 0) := (others => '0');
