        a_internal <= s_axis_a_tdata;
        max_internal <= s_axis_max_tdata;
        min_internal <= s_axis_min_tdata;

        -- Your range adjustment procedure
        if a_internal > max_internal then
          result_internal <= max_internal;
        elsif a_internal < min_internal then
          result_internal <= min_internal;
        else
