sub play-ping-pong {
    my $player1-score = 0;
    my $player2-score = 0;

    loop {
        say "Player 1: $player1-score | Player 2: $player2-score";

        my $input = prompt "Press Enter to hit the ball or 'q' to quit: ";

        last if $input eq 'q';

        my $random = (1..2).roll; # generates random number between 1 and 2

        given $random {
            when 1 {
                say "Player 1 hits the ball!";
                $player1-score++;
            }
            when 2 {
                say "Player 2 hits the ball!";
                $player2-score++;
            }
        }

        if $player1-score >= 10 {
            say "Player 1 wins!";
            last;
        }
        if $player2-score >= 10 {
            say "Player 2 wins!";
            last;
        }
    }
}

play-ping-pong();
