(function() {
    'use strict';

    // Helper function to create an image element
    function createImageElement(link) {
        const img = document.createElement('img');
        img.src = link;
        img.style.maxWidth = '100%';
        return img;
    }

    // Function to process unsee links
    function expandUnseeLinks() {
        const links = document.querySelectorAll('a');

        links.forEach(link => {
            if (link.href.includes('unsee.cc')) {
                // Extract the ID from the unsee link
                const matches = link.href.match(/unsee\.cc\/album\/([a-zA-Z0-9]+)/);
