```perl
#!/usr/bin/perl

use strict;
use warnings;
use DBI;
use Try::Tiny;
use Data::UUID;

# Konfigurationsparameter
my $dsn = "DBI:mysql:database=your_database_name;host=your_host";
my $username = "your_username";
my $password = "your_password";

# Verbinde zur Datenbank
my $dbh = DBI->connect($dsn, $username, $password, {
    RaiseError => 1,
    AutoCommit => 1,
    mysql_enable_utf8 => 1,
}) or die "Could not connect to database: $DBI::errstr";

# UUID-Generator
my $ug = Data::UUID->new;

try {
    # Transaktion starten
    $dbh->begin_work;

    # Abfrage für fällige Contracts
    my $sth = $dbh->prepare(q{
        SELECT Id, Project, ArtId, Quantity, Price, PricingModel, NextBillingOn
        FROM Contracts
        WHERE Status = 'active' AND NextBillingOn <= CURDATE()
    });
    $sth->execute;

    while (my $contract = $sth->fetchrow_hashref) {
        # UUID für neue InvoiceLineItem generieren
        my $invoice_id = $ug->create_str();

        my $invoice_sth = $dbh->prepare(q{
            INSERT INTO InvoiceLineItem (
                Id, ContractId, Project, Status, BillingPeriodStart,
                BillingPeriodEnd, Item, Description, Quantity, Price, PricingModel
            ) VALUES (?, ?, ?, 'ready', CURDATE(), DATE_ADD(CURDATE(), INTERVAL 1 MONTH),
                ?, ?, ?, ?, ?)
        });

        $invoice_sth->execute(
            $invoice_id,
            $contract->{Id},
            $contract->{Project},
            $contract->{ArtId},
            "Beschreibung hier",
            $contract->{Quantity},
            $contract->{Price},
            $contract->{PricingModel}
        );

        # Update Vertrags-Nächste-Rechnung Datum (einfaches Beispiel)
        my $update_sth = $dbh->prepare(q{
            UPDATE Contracts SET NextBillingOn = DATE_ADD(NextBillingOn, INTERVAL 1 MONTH)
            WHERE Id = ?
        });

        $update_sth->execute($contract->{Id});
    }

    # Transaktion bestätigen
    $dbh->commit;

    print "Invoice line items created successfully.\n";
} catch {
    warn "An error occurred: $_";
    # Bei Fehler Transaktion zurückrollen
    eval { $dbh->rollback; };
};

# Verbindung schließen
$dbh->disconnect;
```

### Erläuterungen:

1. **DBI Modul**: Wir verwenden das Perl DBI-Modul für den Datenbankzugriff. Die Fehlerbehandlung wird durch `RaiseError` vereinfacht, da eine Ausnahme ausgelöst wird, wenn ein Fehler auftritt.

2. **Transaktionen**: Wir nutzen Transaktionen für Zuverlässigkeit. Wenn irgendwo ein Fehler auftritt, wird die Transaktion zurückgerollt.

3. **UUID**: Das `Data::UUID` Modul wird verwendet, um eindeutige Bezeichner für die neuen `InvoiceLineItem` Einträge zu erzeugen.

4. **Fehlerbehandlung**: Wir verwenden `Try::Tiny` für robuste Fehlerbehandlung. Es ermöglicht uns, Fehler abzufangen und sicherzustellen, dass die Transaktion im Fehlerfall zurückgerollt wird.

5. **SQL Statements**: Dargestellte SQL-Anweisungen wurden vereinfacht. Sie müssen sicherstellen, dass alle Werte korrekt sind (z.B. BillingPeriod, Beschreibung).

