```csharp
using UnityEngine;

public class CircleGizmo : MonoBehaviour
{
    public Color circleColor = Color.black;

    private void OnDrawGizmos()
    {
        Gizmos.color = circleColor;
        DrawCircle(transform.position, 1f);
        Gizmos.color = Color.white;
        DrawCircle(transform.position, 1.1f);
    }

    private void DrawCircle(Vector3 center, float radius)
    {
        int segments = 360;
        float angle = 0f;
        float angleIncrement = 360f / segments;

        for (int i = 0; i < segments; i++)
        {
            float x = center.x + Mathf.Cos(Mathf.Deg2Rad * angle) * radius;
            float y = center.y + Mathf.Sin(Mathf.Deg2Rad * angle) * radius;

            Vector3 startPoint = new Vector3(x, y, center.z);
            angle += angleIncrement;

            x = center.x + Mathf.Cos(Mathf.Deg2Rad * angle) * radius;
            y = center.y + Mathf.Sin(Mathf.Deg2Rad * angle) * radius;

            Vector3 endPoint = new Vector3(x, y, center.z);

            Gizmos.DrawLine(startPoint, endPoint);
        }
    }
}
```

